command:
const token = canvas.tokens.controlled[0] ?? game.user.character?.getActiveTokens()[0];
const actor = token?.actor ?? game.user.character;
if (!actor) return ui.notifications.warn("请先选中持有妖刀的角色或令牌。");
const weapon = actor.itemTypes.weapon.find(w => (w.system.traits?.otherTags ?? []).includes("jiuli-katana"));
if (!weapon) return ui.notifications.warn("该角色身上没有「妖刀·隐里切」。");
const slug = weapon.system.slug ?? "";
const tier = slug.includes("greater") ? "greater" : slug.includes("moderate") ? "moderate" : "lesser";
const cfg = { lesser: { bleed: "1d4", hours: 8, doom: 1, dc: 19 }, moderate: { bleed: "1d6", hours: 12, doom: 2, dc: 27 }, greater: { bleed: "2d6", hours: 12, doom: 2, dc: 34 } }[tier];
const speaker = ChatMessage.getSpeaker({ actor, token: token?.document });
async function drawBlade() {
  try {
    const cond = game.pf2e.ConditionManager.getCondition("persistent-damage").toObject();
    cond.system.persistent = { formula: cfg.bleed, damageType: "bleed", dc: 15, criticalHit: false };
    delete cond._id;
    await actor.createEmbeddedDocuments("Item", [cond]);
  } catch (e) { console.error("妖刀拔刀流血创建失败，改用聊天卡：", e); }
  await ChatMessage.create({ speaker, content: `<p><strong>拔刀 · 隐里切</strong>：刃饮汝血，你受到 @Damage[(${cfg.bleed})[persistent,bleed]]{持续流血}。</p>` });
}
async function feed() {
  const pack = game.packs.get("wang-pf2e-homebrew.homebrew-items");
  const doc = await pack?.getDocument("whbJiuliSated001");
  if (!doc) return ui.notifications.error("找不到「满足」效果，请先运行 npm run pack。");
  const src = doc.toObject();
  src.system.duration.value = cfg.hours * 60;
  delete src._id;
  const old = actor.itemTypes.effect.filter(e => e.slug === "jiuli-sated");
  if (old.length) await actor.deleteEmbeddedDocuments("Item", old.map(i => i.id));
  await actor.createEmbeddedDocuments("Item", [src]);
  await ChatMessage.create({ speaker, content: `<p><strong>饮血 · 满足</strong>：妖刀暂息 ${cfg.hours} 小时。因血渴累积的毁灭可在下次休息时正常降低。</p>` });
}
async function starve() {
  for (let i = 0; i < cfg.doom; i++) await actor.increaseCondition("doomed", { max: 3 });
  await ChatMessage.create({ speaker, content: `<p><strong>血渴未偿</strong>：${actor.name} 获得 <strong>毁灭 ${cfg.doom}</strong>（上限 3）。在下次饮血前，此毁灭无法通过休息降低。</p>` });
}
new Dialog({
  title: `妖刀·隐里切 控制台（${tier}）`,
  content: `<p>持有者：<strong>${actor.name}</strong></p><p style="font-size:12px">档位 ${tier}｜诅咒 DC ${cfg.dc}｜拔刀流血 ${cfg.bleed}｜满足 ${cfg.hours} 小时｜血渴毁灭 ${cfg.doom}</p>`,
  buttons: {
    draw: { label: "拔刀（自伤流血）", callback: drawBlade },
    feed: { label: "饮血（满足）", callback: feed },
    starve: { label: "血渴结算（毁灭）", callback: starve },
    close: { label: "关闭" }
  },
  default: "close"
}).render(true);
